CREATE TABLE `consents_acupuncture` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `clinic_user_id` int(11) NOT NULL,
  `consenting_date` date DEFAULT NULL,
  `consenting_start_date` date DEFAULT NULL,
  `consenting_end_date` date DEFAULT NULL,
  `benefit_period_start_date` date DEFAULT NULL,
  `benefit_period_end_date` date DEFAULT NULL,
  `first_care_date` date DEFAULT NULL,
  `reconsenting_expiry` date DEFAULT NULL,
  `bill_category_id` int(11) DEFAULT NULL,
  `outcome_id` int(11) DEFAULT NULL,
  `illness_name_acupuncture_id` int(11) DEFAULT NULL,
  `illness_name_acupuncture_addendum` varchar(255) DEFAULT NULL,
  `is_housecall_required` tinyint(1) DEFAULT NULL,
  `housecall_reason_id` bigint(20) unsigned DEFAULT NULL,
  `housecall_reason_addendum` varchar(255) DEFAULT NULL,
  `therapy_period` varchar(255) DEFAULT NULL,
  `first_therapy_content_id` int(11) DEFAULT NULL,
  `condition_id` int(11) DEFAULT NULL,
  `work_scope_type_id` int(11) DEFAULT NULL,
  `onset_and_injury_date` date DEFAULT NULL,
  `consenting_doctor_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `cdh_acupuncture_illness_names_acupuncture_FK` (`illness_name_acupuncture_id`),
  KEY `concenting_doctor_history_acupuncture_bill_categories_FK` (`bill_category_id`),
  KEY `concenting_doctor_history_acupuncture_outcomes_FK` (`outcome_id`),
  KEY `idx_clinic_user_id` (`clinic_user_id`),
  KEY `consents_acupuncture_housecall_reason_id_foreign` (`housecall_reason_id`),
  KEY `consents_acupuncture_consenting_doctor_id_foreign` (`consenting_doctor_id`),
  CONSTRAINT `cdh_acupuncture_illness_names_acupuncture_FK` FOREIGN KEY (`illness_name_acupuncture_id`) REFERENCES `illnesses_acupuncture` (`id`),
  CONSTRAINT `concenting_doctor_history_acupuncture_bill_categories_FK` FOREIGN KEY (`bill_category_id`) REFERENCES `bill_categories` (`id`),
  CONSTRAINT `concenting_doctor_history_acupuncture_outcomes_FK` FOREIGN KEY (`outcome_id`) REFERENCES `outcomes` (`id`),
  CONSTRAINT `consents_acupuncture_consenting_doctor_id_foreign` FOREIGN KEY (`consenting_doctor_id`) REFERENCES `doctors` (`id`) ON DELETE SET NULL,
  CONSTRAINT `consents_acupuncture_housecall_reason_id_foreign` FOREIGN KEY (`housecall_reason_id`) REFERENCES `housecall_reasons` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ccdha_clinic_user_id` FOREIGN KEY (`clinic_user_id`) REFERENCES `clinic_users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='同意医師履歴情報（はり・きゅう）';
