DROP TABLE IF EXISTS `consents_massage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `consents_massage` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `clinic_user_id` int(11) NOT NULL,
  `consenting_doctor_id` int(11) DEFAULT NULL,
  `consenting_date` date DEFAULT NULL,
  `consenting_start_date` date DEFAULT NULL,
  `consenting_end_date` date DEFAULT NULL,
  `benefit_period_start_date` date DEFAULT NULL,
  `benefit_period_end_date` date DEFAULT NULL,
  `first_care_date` date DEFAULT NULL,
  `injury_and_illness_name_id` int(11) DEFAULT NULL,
  `reconsenting_expiry` date DEFAULT NULL,
  `bill_category_id` int(11) DEFAULT NULL,
  `outcome_id` int(11) DEFAULT NULL,
  `is_symptom_1` tinyint(1) DEFAULT NULL,
  `is_symptom_2` tinyint(1) DEFAULT NULL,
  `symtom_2_addendum` varchar(255) DEFAULT NULL,
  `is_symptom_3` tinyint(1) DEFAULT NULL,
  `symtom_3_addendum` varchar(255) DEFAULT NULL,
  `is_therapy_type_1` tinyint(1) DEFAULT NULL,
  `is_therapy_type_2` tinyint(1) DEFAULT NULL,
  `is_housecall_required` tinyint(1) DEFAULT NULL,
  `housecall_reason_id` int(11) DEFAULT NULL,
  `housecall_reason_addendum` varchar(255) DEFAULT NULL,
  `care_level` varchar(255) DEFAULT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `therapy_period` varchar(255) DEFAULT NULL,
  `first_therapy_content_id` int(11) DEFAULT NULL,
  `condition_id` int(11) DEFAULT NULL,
  `work_scope_type_id` int(11) DEFAULT NULL,
  `onset_and_injury_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `accepted_doctor_history_massage_injury_and_illness_names_FK` (`injury_and_illness_name_id`),
  KEY `concenting_doctor_history_massage_therapy_conetnts_FK` (`first_therapy_content_id`),
  KEY `concenting_doctor_history_massage_conditions_FK` (`condition_id`),
  KEY `concenting_doctor_history_massage_work_scope_types_FK` (`work_scope_type_id`),
  KEY `concenting_doctor_history_massage_outcomes_FK` (`outcome_id`),
  KEY `idx_clinic_user_id` (`clinic_user_id`),
  KEY `consents_massage_consenting_doctor_id_foreign` (`consenting_doctor_id`),
  CONSTRAINT `accepted_doctor_history_massage_injury_and_illness_names_FK` FOREIGN KEY (`injury_and_illness_name_id`) REFERENCES `illnesses_massage` (`id`),
  CONSTRAINT `concenting_doctor_history_massage_conditions_FK` FOREIGN KEY (`condition_id`) REFERENCES `conditions` (`id`),
  CONSTRAINT `concenting_doctor_history_massage_outcomes_FK` FOREIGN KEY (`outcome_id`) REFERENCES `outcomes` (`id`),
  CONSTRAINT `concenting_doctor_history_massage_therapy_conetnts_FK` FOREIGN KEY (`first_therapy_content_id`) REFERENCES `therapy_contents` (`id`),
  CONSTRAINT `concenting_doctor_history_massage_work_scope_types_FK` FOREIGN KEY (`work_scope_type_id`) REFERENCES `work_scope_types` (`id`),
  CONSTRAINT `consents_massage_consenting_doctor_id_foreign` FOREIGN KEY (`consenting_doctor_id`) REFERENCES `doctors` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ccdhm_clinic_user_id` FOREIGN KEY (`clinic_user_id`) REFERENCES `clinic_users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='同意医師履歴（あんま・マッサージ）';
/*!40101 SET character_set_client = @saved_cs_client */;

