--
-- Table structure for table `plans`
--

DROP TABLE IF EXISTS `plans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `plans` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `clinic_user_id` int(11) NOT NULL,
  `assessment_date` date NOT NULL,
  `assessor` varchar(255) DEFAULT NULL,
  `audience` varchar(255) DEFAULT NULL,
  `eating_assistance_level_id` int(11) DEFAULT NULL,
  `eating_assistance_note` varchar(255) DEFAULT NULL,
  `moving_assistance_level_id` int(11) DEFAULT NULL,
  `moving_assistance_note` varchar(255) DEFAULT NULL,
  `personal_grooming_assistance_level_id` int(11) DEFAULT NULL,
  `personal_grooming_assistance_note` varchar(255) DEFAULT NULL,
  `using_toilet_assistance_level_id` int(11) DEFAULT NULL,
  `using_toilet_assistance_note` varchar(255) DEFAULT NULL,
  `bathing_assistance_level_id` int(11) DEFAULT NULL,
  `bathing_assistance_note` varchar(255) DEFAULT NULL,
  `walking_assistance_level_id` int(11) DEFAULT NULL,
  `walking_assistance_note` varchar(255) DEFAULT NULL,
  `using_stairs_assistance_level_id` int(11) DEFAULT NULL,
  `using_stairs_assistance_note` varchar(255) DEFAULT NULL,
  `changing_clothes_assistance_level_id` int(11) DEFAULT NULL,
  `changing_clothes_assistance_note` varchar(255) DEFAULT NULL,
  `defecation_assistance_level_id` int(11) DEFAULT NULL,
  `defecation_assistance_note` varchar(255) DEFAULT NULL,
  `urination_assistance_level_id` int(11) DEFAULT NULL,
  `urination_assistance_note` varchar(255) DEFAULT NULL,
  `communication_note` varchar(255) DEFAULT NULL,
  `wish_of_user_and_familiy` varchar(255) DEFAULT NULL,
  `care_purpose` varchar(255) DEFAULT NULL,
  `rehabilitation_program` varchar(255) DEFAULT NULL,
  `home_rehabilitation` varchar(255) DEFAULT NULL,
  `change_since_previous_planning` varchar(255) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `user_and_family_consent_date` date DEFAULT NULL,
